  "implementation": "def solve(case):
    # Validate required fields
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'text' not in case or not isinstance(case['text'], str):
        raise ValueError("missing or invalid 'text'")
    if 'passes' not in case or not isinstance(case['passes'], list):
        raise ValueError("missing or invalid 'passes'")
    if 'max_rounds' not in case or not isinstance(case['max_rounds'], int) or case['max_rounds'] < 0:
        raise ValueError("missing or invalid 'max_rounds'")

    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']

    # Validate each pass
    for p in passes:
        if not isinstance(p, dict) or 'name' not in p or 'old' not in p or 'new' not in p:
            raise ValueError("each pass must be dict with 'name', 'old', 'new'")
        if not isinstance(p['name'], str) or not isinstance(p['old'], str) or not isinstance(p['new'], str):
            raise ValueError("pass fields must be strings")

    applications = []
    fixed_point = False

    for _ in range(max_rounds):
        changed_in_round = False
        for p in passes:
            old = p['old']
            new = p['new']
            idx = text.find(old)
            if idx != -1:
                # Apply first eligible rewrite
                text = text[:idx] + new + text[idx + len(old):]
                applications.append(p['name'])
                changed_in_round = True
        if not changed_in_round:
            fixed_point = True
            break
    else:
        # loop exhausted without break => no fixed point reached
        fixed_point = False

    return {
        'text': text,
        'applications': applications,
        'fixed_point': fixed_point
    }"
}
